indicators.content:
rule PHP_Webshell_Input_To_Exec_Heuristic    
   {    
   meta:    
   description = "PHP files that pass request input to command execution or code evaluation, use an execution function as a string callback, evaluate the raw request body, or open a reverse shell"    
   author = "CYFIRMA Research"    
   date = "2026-10-22"    
   category = "Behavioural Detection"    
   severity = "Medium"    
   note = "Post-exploitation webshell detection in web roots; not PHP2Shell-specific. Validate hits against legitimate application code"    
   strings:    
   $php1 = " php " ascii nocase   
   $php2 = "<?=" ascii   
   // request input passed straight into an execution or evaluation function, optionally through decoders   
   $direct = /[^A-Za-z0-9_ :$](system|exec|shell_exec|passthru|popen|proc_open|pcntl_exec|assert|eval)\s*\(\s*((base64_decode|str_rot13|gzinflate|gzuncompress|rawurldecode)\s*\(\s*)*\$_(GET|POST|REQUEST|COOKIE|SERVER)/ nocase    
   // backtick operator executing request input    
   $backtick = /`[^`\n]{0,200}\$_(GET|POST|REQUEST|COOKIE)/    
   // variable function called with request input, e.g. $f($_REQUEST[x])    
   $var_func = /\$[a-zA-Z_][a-zA-Z0-9_]*\s*\(\s*\$_(GET|POST|REQUEST|COOKIE)\s*\[/    
   // request input used as the function name, e.g. $_GET[f]($_GET[c])    
   $input_func = /\$_(GET|POST|REQUEST|COOKIE)\s*\[[^\]\n]{1,40}\]\s*\(/    
   // execution function passed as a string callback, e.g. call_user_func(system, )    
   // (callback as first argument; method callbacks such as array($pdo, exec) are deliberately not matched)    
   $str_cb1 = /(call_user_func(_array)?|array_map|register_shutdown_function)\s*\(\s*["](system|exec|shell_exec|passthru|popen|proc_open|assert)["]/ nocase    
   // (callback as second argument after an array variable)    
   $str_cb2 = /(array_filter|array_walk|usort|uasort|uksort)\s*\(\s*\$[A-Za-z0-9_]{1,40}\s*,\s*["](system|exec|shell_exec|passthru|popen|proc_open|assert)["]/ nocase    
   // raw request body evaluated or included    
   $php_input = /(eval|assert|include|include_once|require|require_once)\s*\(?\s*(file_get_contents\s*\(\s*)?["]php:\/\/input/ nocase    
   // reverse shell: socket plus interactive shell    
   $fsock = /fsockopen\s*\(/ nocase    
   $shell_i = /\/bin\/(ba)?sh -i|\/dev\/tcp\//    
   condition:    
   filesize < 1MB and   
   any of ($php*) and   
   (   
   $direct or $backtick or $var_func or $input_func or $str_cb1 or $str_cb2 or $php_input or   
   ($fsock and $shell_i)   
   )   
   }
